// Integration tests for the battery‑warden CLI\n\nuse assert_cmd::Command;\n\n#[test]\nfn cli_estimates_hours() {\n    let mut cmd = Command::cargo_bin("battery-warden").unwrap();\n    cmd.arg("5000").arg("250");\n    cmd.assert()\n        .success()\n        .stdout(predicates::str::contains("Estimated remaining time: 20.00 hours"));\n}\n\n#[test]\nfn cli_apocalypse_mode() {\n    let mut cmd = Command::cargo_bin("battery-warden").unwrap();\n    cmd.args(&["5003", "250", "--apocalypse"]);\n    cmd.assert()\n        .success()\n        .stdout(predicates::str::contains("Apocalypse tip: Keep a spare battery pack in your bunker."));\n}\n
